"""Individually authored SP96 source; not yet delivered or runtime validated.

Domestic procedures and all quantitative effects are provisional gameplay.
The compiler must bind every node's purpose to real owned runtime before this
source can count toward the approved national programme.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class Branch:
    tag: str
    key: str
    opens: str
    institution: str
    context: str
    titles: tuple[str, ...]
    scenes: tuple[str, ...]
    policies: tuple[tuple[str, dict, dict], ...]
    services: tuple[tuple[str, str, dict], ...]
    motifs: tuple[str, str]


def branch(tag, key, opens, institution, context, titles, scenes, policies, services, motifs):
    assert len(titles) == len(scenes) == 6
    assert len(policies) == len(services) == len(motifs) == 2
    return Branch(tag, key, opens, institution, context, tuple(titles), tuple(scenes),
                  tuple(policies), tuple(services), tuple(motifs))


